// Quem reverifica o acervo INTEIRO é o operador, pelo gatilho Manual (ADR-014: mudar número é decisão).
// Chamado por outro fluxo (W11 "Reverificar", testes): só os `controles` dados, ou todos com `todos: true` EXPLÍCITO.
// Sem lista e sem `todos` = nenhum. Nunca "todos" por omissão: em 24/09 um teste que pedia 2 licitações chegou
// aqui sem os itens e reverificou o acervo publicado inteiro (execução 436, desfeita à mão).
const RE = /^\d{14}-\d+-\d+\/\d{4}$/;
const j = $input.first().json || {};
const manual = $('Manual').isExecuted;
let controles = j.controles ?? null;
if (typeof controles === 'string') {
  const t = controles.trim();
  try { controles = t.startsWith('[') ? JSON.parse(t) : t.split(',').map((s) => s.trim()).filter(Boolean); }
  catch (e) { throw new Error('controles ilegível: ' + t.slice(0, 120)); }
}
if (controles !== null && !Array.isArray(controles)) controles = [controles];
if (Array.isArray(controles)) {
  controles = [...new Set(controles.map((c) => String(c).trim()))];
  const ruins = controles.filter((c) => !RE.test(c));
  if (ruins.length) throw new Error('controle fora do formato CNPJ-1-SEQ/ANO: ' + ruins.join(', '));
}
const todos = controles === null && (manual || j.todos === true || j.todos === 'true');
if (controles === null && !todos) controles = [];
return [{ json: { controles, todos, gatilho: manual ? 'manual' : $execution.mode } }];

// Uma licitação por volta (em série): a reverificação é CPU do worker e o W24 troca a vigente dela.
const a = $input.first().json;
return [{ json: { controle: a.controle, vigente_id: Number(a.vigente_id), execucao_id: Number(a.execucao_id),
  versao_antes: a.versao_antes, estado: a.estado } }];

// O que aconteceu com ESTA licitação (o item volta ao laço; o resumo sai quando o laço termina).
const a = $('Alvo').first().json;
const j = $input.first().json || {};
let r;
if (j.modo !== undefined && j.ok !== undefined) {                   // voltou do W24
  const mudaram = Object.keys((j.diff && j.diff.vereditos) || {});
  r = { controle: a.controle, ok: j.ok === true, antes: a.vigente_id, depois: j.verificacao_id ? Number(j.verificacao_id) : null,
        versao_antes: a.versao_antes, mudaram, diff: j.diff || null, email_id: j.email_id ?? null,
        estado: j.estado ?? null, motivo: j.motivo ?? null };
} else if (Object.keys(j).length === 0) {                            // 409 e nada a republicar
  r = { controle: a.controle, ok: true, pulada: true, antes: a.vigente_id, depois: null, mudaram: [],
        motivo: 'já verificada nesta versão das regras e sem verificação pendente de republicar' };
} else {                                                             // /reverificar falhou
  let motivo;
  if (j.error) motivo = 'worker sem resposta: ' + String(j.error.message || JSON.stringify(j.error)).slice(0, 240);
  else motivo = `/reverificar HTTP ${j.statusCode}: ` + (typeof j.body === 'string' ? j.body : JSON.stringify(j.body ?? '')).slice(0, 300);
  r = { controle: a.controle, ok: false, antes: a.vigente_id, depois: null, mudaram: [], motivo };
}
return [{ json: { resultado: r } }];

// regra — antes/depois da rodada (plano §5 W30 passo 4): quantas reverificadas, quantas mudaram de veredito, falhas,
// pendentes de leitura. Custo R$ 0: nem modelo nem OCR.
const pan = $('Panorama').first().json;
const versao = $('GET /versao').first().json.versao_regras;
const rs = $input.all().map((i) => i.json && i.json.resultado).filter(Boolean);
const republicadas = rs.filter((r) => r.ok && r.depois && !r.pulada);
const falhas = rs.filter((r) => !r.ok);
return [{ json: {
  versao_regras: versao,
  status: falhas.length ? 'erro' : 'ok',
  contadores: {
    vigentes: Number(pan.vigentes), a_reverificar: Number(pan.a_reverificar), ja_na_versao: Number(pan.ja_na_versao),
    pendentes_de_leitura: Number(pan.pendentes_de_leitura), reverificadas: rs.length,
    republicadas: republicadas.length, com_veredito_mudado: republicadas.filter((r) => r.mudaram.length).length,
    vereditos_mudados: republicadas.reduce((t, r) => t + r.mudaram.length, 0),
    puladas: rs.filter((r) => r.pulada).length, falhas: falhas.length,
  },
  resultados: rs,
  erro: falhas.length ? falhas.map((f) => `${f.controle}: ${f.motivo}`).join(' | ').slice(0, 2000) : null,
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const site = String($env.FOPA_SITE_PUBLIC_URL || '').replace(/\/+$/, '');
const n8nBase = String($env.WEBHOOK_URL || '').replace(/\/+$/, '');
const linkExecucao = `${n8nBase}/workflow/${$workflow.id}/executions/${$execution.id}`;
// regra — UM e-mail por rodada (plano §5 W30 passo 4), na fila; o W50 envia. Cada licitação republicada já tem o seu
// 'republicada' com o diff; este é o panorama.
const s = $('Resumo da rodada').first().json;
const c = s.contadores;
const vr = String(s.versao_regras || '').slice(0, 12);
const assunto = `[FOPA] Reverificação: ${c.republicadas} republicada(s), ${c.com_veredito_mudado} com veredito mudado`
  + (c.falhas ? `, ${c.falhas} falha(s)` : '') + ` · regras ${vr}`;
const linhas = s.resultados.map((r) => {
  const slug = String(r.controle).replace('/', '-');
  const o = r.pulada ? 'pulada' : (r.ok ? 'republicada' : 'FALHOU');
  return `<tr><td><a href="${esc(site)}/licitacao/${esc(slug)}">${esc(r.controle)}</a></td><td>${esc(o)}</td>`
    + `<td>${esc(r.antes ?? '—')} → ${esc(r.depois ?? '—')}</td>`
    + `<td>${r.mudaram.length ? esc(r.mudaram.join(', ')) : '—'}</td><td>${esc(r.motivo || '')}</td></tr>`;
}).join('');
const corpo = [
  `<p>Regras atuais: <code>${esc(s.versao_regras)}</code>. Reverificação sem modelo e sem OCR novo (ADR-011): custo R$ 0,00.</p>`,
  `<p>${c.vigentes} vigente(s) no alcance · ${c.a_reverificar} em versão antiga · ${c.ja_na_versao} já na versão · `
    + `${c.pendentes_de_leitura} pendente(s) de leitura (sem texto congelado, não reverificáveis).</p>`,
  `<p>${c.reverificadas} reverificada(s): ${c.republicadas} republicada(s), ${c.com_veredito_mudado} com veredito mudado `
    + `(${c.vereditos_mudados} veredito(s) no total), ${c.puladas} pulada(s), ${c.falhas} falha(s).</p>`,
  linhas ? `<table border="1" cellpadding="4" cellspacing="0"><tr><th>Controle</th><th>Resultado</th><th>Verificação</th>`
    + `<th>Mudaram</th><th>Motivo</th></tr>${linhas}</table>` : '<p>Nada a reverificar.</p>',
  `<p><a href="${esc(site)}/execucoes">Execuções no site</a> · <a href="${esc(linkExecucao)}">execução ${esc($execution.id)} no n8n</a></p>`,
].join('');
return [{ json: { assunto, corpo_html: corpo } }];

const s = $('Resumo da rodada').first().json;
return [{ json: { ok: s.status === 'ok', versao_regras: s.versao_regras, ...s.contadores, resultados: s.resultados,
  execucao_workflow_id: $('Abrir execução W30').first().json.execucao_workflow_id,
  email_id: $json.email_id } }];
